from produire import produire
from format_lecon import paras,table,steps
from medicaments import ceftriaxone

p=[
('La {pharyngite gonococcique} est une infection oropharyngée par Neisseria gonorrhoeae. Elle peut être peu symptomatique ou silencieuse. L’exposition et le site du prélèvement sont essentiels au diagnostic.',paras('Une gonorrhée génitale ou un test urinaire ne renseigne pas automatiquement sur le pharynx. Les prélèvements doivent correspondre aux sites exposés.', 'La présence d’un mal de gorge ne prouve pas que le gonocoque en est la cause. Il faut relier les résultats à l’examen et considérer les autres diagnostics.')),
('Le {risque dépend des contacts sexuels}. L’absence de symptômes ne protège pas de la transmission. Une évaluation individualisée évite les présupposés sur les personnes.',paras('La directive SSI validée le 23 octobre 2026 indique que les infections pharyngées et rectales sont asymptomatiques dans plus de 90 % des cas. Cette proportion concerne ces localisations et non toutes les formes de gonorrhée.', 'Une fréquence suisse actuelle propre aux pharyngites symptomatiques n’est pas fournie dans les sources consultées. Le rang dans le diagnostic différentiel est lié à l’exposition, pas à un classement général mesuré.')),
('L’{infection muqueuse peut constituer un réservoir silencieux}. La PCR identifie le matériel bactérien et la culture étudie la sensibilité. Le traitement tient compte de la résistance.',table(['Perturbation','Exploration','Réponse'],[['Infection pharyngée.','Prélèvement du pharynx pour PCR et culture.','Antibiotique adapté à la recommandation et à la sensibilité.'],['Réinfection par un contact non traité.','Anamnèse et suivi des partenaires.','Prise en charge des contacts et prévention.'],['Dissémination systémique.','Signes articulaires, cutanés ou généraux ; prélèvements ciblés.','Évaluation hospitalière et traitement différent de la forme localisée.']])+paras('La SSI souligne la diminution de sensibilité aux céphalosporines et à l’azithromycine à l’échelle internationale. La culture apporte donc une information que la seule PCR ne donne pas.')),
('Le {tri recherche une infection compliquée et les autres causes de gorge douloureuse}. Les signes respiratoires ou d’abcès gardent leur priorité. Une fièvre avec manifestations articulaires ou cutanées exige de chercher une dissémination.',table(['Concurrent ou complication','Indice','Conduite'],[['🚩 Abcès ou épiglottite.','Trismus, salivation, stridor ou asymétrie.','Urgence ORL selon gravité.'],['🚩 Gonococcémie disséminée.','Arthrite, ténosynovite, pustules ou syndrome général.','Bilan spécialisé urgent.'],['Primo-infection VIH ou syphilis.','Exposition et tableau compatibles.','Dépistage adapté avec consentement.'],['Pharyngite virale ou streptococcique.','Tableau respiratoire ou amygdalien habituel.','Évaluer sans attribuer toute douleur à une IST.']])) ,
('L’{anamnèse sexuelle se fait sans jugement}. Demander les pratiques et les sites exposés. Préciser symptômes génitaux, rectaux et signes généraux.',paras('La question des contacts oraux explique le prélèvement pharyngé. Rechercher le délai d’apparition, les partenaires récents, une infection connue chez un partenaire et les traitements déjà pris.', 'Évaluer grossesse, allaitement, allergies aux bêta-lactamines et antécédents de réactions à la lidocaïne si une injection intramusculaire est envisagée. La confidentialité et le consentement font partie de la consultation.')),
('L’{examen pharyngé peut être normal}. Une rougeur ou un exsudat est non spécifique. Rechercher les signes d’une localisation compliquée.',paras('Inspecter bouche et pharynx si le patient est stable, sans conclure sur la seule couleur. Le prélèvement dépend de l’exposition, même si la muqueuse paraît banale.', 'Selon les symptômes et le consentement, examiner les autres sites et rechercher arthrite, ténosynovite ou lésions cutanées. Un tableau systémique ne relève plus du simple traitement localisé.')),
('L’{approche syndromique distingue portage, pharyngite et dissémination}. Les formes silencieuses sont fréquentes. Chaque localisation commande ses prélèvements.',paras('<em>7.1 — Infection pharyngée silencieuse.</em> Découverte lors d’un dépistage d’exposition ; l’absence de douleur ne signifie pas absence d’infection.', '<em>7.2 — Pharyngite symptomatique.</em> Douleur ou inflammation, dont la spécificité est faible.', '<em>7.3 — Infection disséminée.</em> Signes articulaires, tendineux, cutanés ou généraux imposant un bilan élargi.')),
('Le {diagnostic exige un prélèvement du site concerné}. La SSI recommande PCR et culture. L’antibiogramme aide à adapter le traitement et à documenter un échec.',paras('La PCR est plus sensible que la culture selon la directive suisse. La culture doit être acheminée rapidement avec la mention de suspicion de gonocoque et dans le milieu adapté au laboratoire.', 'Un test sur un autre site ne remplace pas celui du pharynx. Un résultat positif doit être interprété avec le laboratoire et le contexte, notamment en cas de contrôle après traitement.')),
('Les {examens associent confirmation et dépistage des co-infections}. Le contrôle de guérison doit être planifié. Un prélèvement trop précoce pour PCR peut être difficile à interpréter.',table(['Étape','Conduite'],[['9.a : pharynx.','PCR et culture avant traitement si cela ne retarde pas une prise en charge urgente.'],['9.b : autres sites.','Prélèvements génitaux ou rectaux selon expositions et symptômes.'],['9.c : co-infections.','Tests VIH et syphilis, recherche de chlamydia et vérification de la vaccination contre l’hépatite B selon SSI.'],['9.d : contrôle.','SSI conseille contrôle microbiologique au plus tard à 7 jours ; si symptômes persistent au-delà de 2 jours, culture et recherche de résistance. Une PCR de contrôle est envisagée à 10–14 jours.']])) ,
('L’{algorithme relie diagnostic, traitement et partenaires}. Le schéma dépend du caractère localisé ou disséminé. La persistance des symptômes demande une culture et un avis.',steps('Évaluer gravité et signes de dissémination.','Prélever le pharynx et les autres sites indiqués, avec PCR et culture.','Traiter selon la recommandation suisse actuelle en vérifiant la notice et les allergies.','Organiser dépistage des co-infections, information et prise en charge des partenaires.','Planifier le contrôle microbiologique et réévaluer rapidement tout échec.')),
('La {prise en charge suit la recommandation SSI actualisée}. Le traitement contemporain diffère de la dose historique de certaines notices. Cette divergence doit être clairement documentée.',paras('<em>11.A — Situation compliquée.</em> Gonococcémie, infection haute ou atteinte d’organe nécessitent une autre stratégie spécialisée.', '<em>11.B — Forme oropharyngée.</em> @@MEDICAMENTS@@', '<em>11.C — Partenaires et déclaration.</em> La SSI recommande information, dépistage et traitement des partenaires des deux derniers mois. Le médecin organise aussi la déclaration selon la procédure cantonale.', '<em>11.D — Suivi.</em> La directive demande d’éviter les relations sexuelles, y compris orales, pendant une semaine après le début du traitement. Le contrôle vérifie réponse, résistance et réinfection possible ; les partenaires doivent être pris en charge.')),
('La {prévention combine protection, dépistage et traitement des contacts}. Une infection silencieuse peut persister sans examen ciblé. Le suivi évite de confondre résistance et nouvelle exposition.',paras('Expliquer les moyens de protection adaptés aux pratiques et les modalités de dépistage. Vérifier les vaccins pertinents, notamment hépatite B selon la directive suisse.', 'La notification des partenaires se fait dans un cadre confidentiel, avec l’accompagnement du soignant. Le cours décrit cette prise en charge ; il ne remplace pas une décision clinique individuelle.')),
('Le {point clé est le prélèvement du pharynx exposé}. Un examen normal et un test urinaire ne suffisent pas. Le contrôle microbiologique et les partenaires font partie du traitement.',paras('La dose de 0,25 g mentionnée dans la notice Rocephin pour la blennorragie n’est pas présentée comme le schéma actuel de gonorrhée pharyngée. La SSI 2026 recommande 1 g, avec prise en compte du caractère hors modalités de cette information professionnelle.'))]
q=[('La pharyngite gonococcique est-elle toujours douloureuse ?','Non, elle est souvent asymptomatique.'),('Un test urinaire exclut-il une infection pharyngée ?','Non.'),('Quel prélèvement est nécessaire si le pharynx est exposé ?','Un prélèvement pharyngé adapté.'),('Pourquoi associer culture et PCR ?','La PCR est sensible et la culture permet l’étude de sensibilité.'),('Un examen de gorge normal exclut-il ?','Non.'),('Quelles manifestations font rechercher une dissémination ?','Arthrite, ténosynovite, lésions cutanées ou signes généraux.'),('La SSI actuelle recommande-t-elle automatiquement l’ancienne bithérapie du diaporama HUG 2023 ?','Non ; suivre la directive actualisée et les co-infections documentées.'),('Quelle divergence de dose est explicitée ?','SSI 1 g de ceftriaxone versus notice Rocephin 0,25 g pour la blennorragie.'),('Une solution avec lidocaïne peut-elle être injectée par voie intraveineuse ?','Jamais.'),('Quel enjeu particulier pendant la grossesse ?','La notice impose une préparation sans lidocaïne si le traitement est indispensable.'),('Que faire si les symptômes persistent après plus de deux jours ?','Nouveau prélèvement pour culture, recherche de résistance et avis spécialisé selon SSI.'),('Quand la SSI envisage-t-elle une PCR de contrôle ?','À 10–14 jours après traitement.'),('Quels partenaires doivent être pris en compte selon SSI ?','Ceux des deux derniers mois.'),('Faut-il dépister VIH et syphilis ?','Oui selon la prise en charge SSI, avec information et consentement.')]
produire(8,p,q,(3,8,14),ceftriaxone)

p=[
('La {diphtérie respiratoire} est une infection des voies respiratoires liée à une corynébactérie potentiellement toxinogène. Une pseudomembrane adhérente est évocatrice de la forme classique. L’isolement et l’avis spécialisé commencent dès la suspicion.',paras('Les recommandations OFSP 2024 distinguent forme classique, forme respiratoire plus légère et infection cutanée. La recherche de toxigénicité précise la capacité de la souche à produire la toxine.', 'La détection d’une corynébactérie ne se résume donc pas à un diagnostic binaire sans caractérisation. La présentation clinique et l’identification de l’agent guident les mesures.')),
('Le {statut vaccinal et l’exposition orientent le risque}. La maladie reste rare en Suisse. Une vaccination incomplète ou inconnue renforce l’attention sans constituer une preuve.',paras('L’OFSP a décrit une augmentation des cas en 2022, surtout chez des personnes incomplètement vaccinées ou de statut inconnu. Aucun chiffre actuel n’est extrapolé à partir de cette observation.', 'La vaccination protège efficacement contre les formes toxiniques graves, mais n’empêche pas nécessairement la colonisation. Une personne vaccinée peut donc encore entrer dans une enquête autour d’un cas.')),
('La {toxine peut provoquer des lésions à distance}. L’infection locale et les effets toxiniques appellent des traitements complémentaires. L’antibiotique ne neutralise pas à lui seul la toxine déjà produite.',table(['Mécanisme','Recherche','Réponse'],[['Infection respiratoire et membrane.','Examen prudent, prélèvements du nez et du pharynx.','Isolement, antibiothérapie et surveillance respiratoire.'],['Production de toxine.','Recherche du gène ou de la toxine selon laboratoire.','Discussion immédiate d’antitoxine avec infectiologue.'],['Effets systémiques.','Surveillance cardiaque, neurologique et clinique.','Soins hospitaliers et traitement des complications.']])+paras('L’OFSP cite notamment myocardite et polyneuropathie parmi les complications toxiniques. La sérothérapie doit être envisagée précocement lorsque le tableau le justifie, sans attendre l’installation de lésions importantes.')),
('Le {tri recherche obstruction et effets systémiques}. Une pseudomembrane n’est pas une angine banale à gratter. Les diagnostics concurrents ne doivent pas retarder les précautions.',table(['Concurrent','Indice','Action'],[['🚩 Épiglottite ou abcès.','Stridor, salivation, trismus ou foyer profond.','Urgence respiratoire ou ORL.'],['Mononucléose.','Exsudat, adénopathies et fatigue.','Bilan adapté, sans abandonner l’isolement si diphtérie plausible.'],['Angine streptococcique.','Tableau compatible mais non spécifique.','Ne pas laisser un test rapide détourner d’une membrane suspecte.'],['Autre lésion ulcéronécrotique.','Aspect et contexte atypiques.','Avis spécialisé et microbiologie ciblée.']])) ,
('L’{anamnèse recherche vaccination et contacts}. Demander début des symptômes, difficultés respiratoires et contexte de voyage ou d’exposition. Rechercher aussi des lésions cutanées.',paras('La caractérisation des contacts aide à prévenir la transmission. Le contexte doit être individualisé ; une origine ou une appartenance ne remplace pas l’évaluation clinique.', 'Interroger sur palpitations, malaise, faiblesse ou symptômes neurologiques pouvant accompagner une atteinte systémique. Préciser les traitements déjà pris avant les prélèvements.')),
('L’{examen doit être prudent et protégé}. Évaluer respiration, cou, déglutition et état général. Ne pas tenter d’arracher une membrane adhérente.',paras('La forme classique définie par l’OFSP associe une affection respiratoire supérieure à une membrane ou pseudomembrane adhérente. Une tuméfaction cervicale ou une gêne respiratoire accroît la gravité.', 'Les mesures de protection du personnel et l’isolement gouttelettes sont engagés dès la suspicion respiratoire. L’OFSP demande une protection vaccinale complète et à jour pour le personnel qui prend en charge le cas.')),
('L’{approche syndromique sépare atteinte locale et toxicité}. Les formes respiratoires peuvent varier en intensité. Une forme cutanée associée change les prélèvements et les précautions.',paras('<em>7.1 — Syndrome respiratoire local.</em> Mal de gorge, déglutition douloureuse et membrane adhérente dans la forme classique.', '<em>7.2 — Syndrome obstructif.</em> Voix modifiée, dyspnée ou stridor exigent une prise en charge respiratoire urgente.', '<em>7.3 — Syndrome toxinique.</em> Signes cardiaques, neurologiques ou généraux imposent surveillance et avis infectiologique immédiat.')),
('Le {diagnostic nécessite une microbiologie spécifique}. Le laboratoire doit connaître la suspicion. L’identification et la recherche de toxigénicité complètent la clinique.',paras('L’OFSP recommande culture bactériologique et recherche rapide de la toxigénicité. La PCR peut détecter le gène de la toxine ; un test d’Elek peut mettre en évidence sa production selon les possibilités du laboratoire.', 'Les critères de classification et les mesures varient selon l’espèce et les résultats. Un test streptococcique ne répond pas à cette question diagnostique.')),
('Les {examens documentent l’agent et le retentissement}. Les prélèvements précèdent si possible l’antibiotique sans retarder une urgence. La déclaration accompagne la démarche.',table(['Étape','Conduite'],[['9.a : prélèvements.','Frottis du nez et du pharynx/amygdales ; prélèvement cutané si lésion.'],['9.b : identification.','Culture et détermination de l’espèce avec laboratoire averti.'],['9.c : toxigénicité.','Recherche du gène par PCR ou de la toxine selon laboratoire spécialisé.'],['9.d : surveillance.','Bilan des effets cardiaques, neurologiques et autres atteintes selon clinique ; coordination avec infectiologie.']])+paras('Selon OFSP 2024, le médecin déclare dans les 24 heures la suspicion clinique accompagnée d’une demande de diagnostic spécifique ou un résultat positif. Les obligations du laboratoire sont également précisées par l’OFSP.')),
('L’{algorithme commence par isoler et alerter}. L’attente d’une confirmation ne doit pas retarder les mesures. La toxine et la transmission sont prises en charge en parallèle.',steps('Suspecter devant tableau et contexte compatibles, évaluer respiration.','Isoler en gouttelettes à l’hôpital et contacter infectiologue et médecin cantonal.','Organiser les prélèvements spécifiques puis commencer le traitement antibiotique sans retard évitable.','Évaluer immédiatement l’indication de l’antitoxine avec l’infectiologue.','Surveiller complications, organiser contacts et vaccination, puis contrôler l’éradication.')),
('La {prise en charge associe soins hospitaliers et santé publique}. L’antitoxine doit être discutée tôt. L’antibiothérapie et la vaccination répondent à des objectifs différents.',paras('<em>11.A — Stabilisation et isolement.</em> Préserver la voie aérienne et instaurer l’isolement gouttelettes dès la suspicion respiratoire.', '<em>11.B — Infection.</em> L’OFSP demande de commencer l’antibiothérapie immédiatement après les prélèvements pour une suspicion respiratoire. Le choix est adapté avec l’infectiologue ; aucun dosage non vérifié en information professionnelle suisse n’est présenté comme une prescription standard.', '<em>11.C — Toxine.</em> L’OFSP recommande une antitoxine précoce dans une suspicion classique avec vaccination inconnue ou incomplète, et une administration immédiate si effets systémiques importants. Sa commande passe par Tox Info Suisse et le piquet de la Pharmacie de l’armée. Le produit, la voie, la dose et le risque d’hypersensibilité sont gérés par le spécialiste ; ce cours ne transforme pas la procédure en auto-administration.', '<em>11.D — Contacts et suivi.</em> L’OFSP prévoit prélèvements, antibioprophylaxie selon exposition, surveillance et mise à jour vaccinale. La guérison ne dispense pas de compléter une vaccination insuffisante.')),
('La {prévention repose sur vaccination et gestion des contacts}. La levée d’isolement suit des critères microbiologiques. Elle ne dépend pas seulement de la disparition de la fièvre.',paras('Pour la forme respiratoire confirmée, OFSP 2024 permet au plus tôt la levée après deux prélèvements du nez et du pharynx/amygdales négatifs. Ils sont espacés d’au moins 24 heures et réalisés au moins 24 heures après la fin de l’antibiothérapie.', 'La définition des contacts inclut l’exposition étroite pendant les sept jours précédant les symptômes et jusqu’à la fin de l’isolement. Le médecin cantonal et l’équipe d’hygiène organisent les mesures ; les personnes vaccinées ne sont pas automatiquement exemptées de toute action.')),
('Le {point clé est d’agir dès la suspicion}. La prévention de la transmission et la neutralisation de la toxine sont urgentes. Un résultat de laboratoire affine la conduite sans justifier une attente dangereuse.',paras('Le risque respiratoire reste prioritaire. Le suivi du cas et des contacts doit être coordonné avec les autorités et les spécialistes suisses.'))]
q=[('Quel aspect évoque la forme respiratoire classique ?','Une membrane ou pseudomembrane adhérente.'),('Faut-il arracher la membrane ?','Non.'),('Un test streptococcique exclut-il la diphtérie ?','Non.'),('Quand commence l’isolement respiratoire ?','Dès la suspicion, selon le parcours hospitalier OFSP.'),('La vaccination empêche-t-elle toute colonisation ?','Non.'),('Que doit rechercher le laboratoire en plus de la bactérie ?','Sa toxigénicité.'),('Que montre la PCR ciblée sur la toxine ?','La présence du gène recherché ; le test d’Elek recherche la production selon les possibilités du laboratoire.'),('Faut-il attendre une confirmation tardive pour discuter l’antitoxine ?','Non.'),('L’antibiotique neutralise-t-il à lui seul la toxine déjà produite ?','Non.'),('Par quelle filière suisse obtenir l’antitoxine selon OFSP ?','Tox Info Suisse et le piquet de la Pharmacie de l’armée.'),('Quel délai de déclaration médicale cite OFSP 2024 ?','24 heures dans les situations définies.'),('Une fièvre disparue suffit-elle à lever l’isolement ?','Non.'),('Quels contrôles conditionnent au plus tôt la levée après traitement ?','Deux prélèvements négatifs espacés d’au moins 24 heures et commencés au moins 24 heures après la fin de l’antibiothérapie.'),('La maladie dispense-t-elle d’un rattrapage vaccinal ?','Non.')]
produire(9,p,q,(3,4,5,7))

p=[
('Le {carcinome épidermoïde de l’oropharynx} est une tumeur maligne de la muqueuse oropharyngée. Il peut se manifester par une douleur persistante ou une masse cervicale. La confirmation repose sur un prélèvement histologique.',paras('L’oropharynx comprend notamment les amygdales et la base de langue. Une douleur projetée à l’oreille peut être ressentie alors que l’otoscopie est normale.', 'Le diagnostic ne se déduit pas du seul tabagisme ni de l’apparence d’une angine. Une lésion persistante nécessite une évaluation spécialisée.')),
('Le {contexte de risque comprend tabac, alcool et papillomavirus}. L’absence d’exposition connue n’exclut pas une tumeur. Les chiffres anciens du support suisse ne sont pas repris comme statistiques actuelles.',paras('Les HUG 2019 associent les cancers oropharyngés à ces facteurs et soulignent les localisations amygdaliennes et de base de langue pour les tumeurs liées au papillomavirus. Aucune incidence suisse récente spécifique n’est affirmée dans ce cours.', 'Une plainte unilatérale, progressive ou persistante au-delà de trois semaines constitue une alerte ORL dans ce support. Une lésion fortement suspecte ou une masse ne doit toutefois pas attendre ce délai avant orientation.')),
('L’{infiltration locale perturbe douleur et déglutition}. Une propagation ganglionnaire peut rendre la masse cervicale plus évidente que la lésion primaire. Le bilan précise les territoires atteints.',table(['Perturbation','Exploration','Réponse thérapeutique'],[['Lésion muqueuse infiltrante.','Examen ORL, endoscopie et biopsie.','Traitement local adapté à la tumeur.'],['Atteinte ganglionnaire.','Palpation et imagerie du cou ; prélèvement selon spécialiste.','Traitement régional intégré au plan oncologique.'],['Retentissement fonctionnel.','Évaluation de déglutition, nutrition et voix.','Soutien nutritionnel et réadaptation avec l’équipe.']])+paras('La classification TNM décrit l’extension de la tumeur, les ganglions et les métastases. Le stade n’est pas déterminé par l’intensité de la douleur seule.')),
('Le {tri distingue urgence fonctionnelle et suspicion oncologique}. Une hémorragie ou une obstruction impose une prise en charge immédiate. Une plainte persistante sans détresse exige une orientation rapide.',table(['Concurrent','Indice','Action'],[['🚩 Abcès profond.','Fièvre, trismus, progression aiguë.','Urgence infectieuse et ORL.'],['Lésion inflammatoire ou infectieuse.','Évolution et contexte compatibles, résolution attendue.','Vérifier la guérison plutôt que supposer une bénignité durable.'],['Reflux ou irritation.','Contexte chronique sans preuve tumorale.','Ne retenir qu’après évaluation des signes d’alarme.'],['Autre tumeur ORL.','Localisation ou histologie différente.','Bilan spécialisé ; ne pas attribuer tout cancer au même site.']])) ,
('L’{anamnèse précise durée, progression et latéralité}. Demander gêne à avaler, otalgie, voix et perte de poids. Rechercher les expositions sans en faire une condition obligatoire.',paras('Une otalgie du même côté, une masse cervicale ou une gêne croissante à la déglutition renforcent l’indication d’examen ORL. Préciser saignements, alimentation et retentissement quotidien.', 'Documenter tabac, alcool, antécédents de tumeur et traitements déjà essayés. Une amélioration partielle sous antibiotique ou antalgique n’établit pas la bénignité.')),
('L’{examen comprend bouche, oropharynx, oreilles et cou}. Une lésion visible doit être décrite. L’absence de lésion accessible ne dispense pas d’endoscopie si les signes persistent.',paras('Inspecter asymétrie amygdalienne, ulcération ou masse chez une personne stable. Palper les aires ganglionnaires et réaliser une otoscopie lorsque l’oreille est douloureuse.', 'La base de langue et d’autres régions ne sont pas entièrement évaluées par une inspection simple. Le spécialiste complète par endoscopie et choisit les prélèvements.')),
('L’{approche syndromique relie lésion, ganglions et fonction}. Les trois dimensions peuvent être inégalement visibles. Le retentissement doit être pris en charge pendant le bilan.',paras('<em>7.1 — Syndrome local.</em> Douleur persistante, ulcération, gêne à avaler ou otalgie réflexe.', '<em>7.2 — Syndrome ganglionnaire.</em> Masse cervicale parfois révélatrice d’un primitif peu visible.', '<em>7.3 — Retentissement général et fonctionnel.</em> Réduction des apports, amaigrissement, altération de la voix ou de la déglutition.')),
('Le {diagnostic positif est histologique}. L’examen clinique suspecte et localise. L’imagerie évalue l’extension mais ne remplace pas l’analyse tissulaire.',paras('Les HUG décrivent une démarche associant anamnèse, examen ORL, imagerie, endoscopie et biopsies. L’équipe choisit le site du prélèvement et l’analyse nécessaire.', 'Le statut lié au papillomavirus et les caractéristiques histologiques peuvent influencer le classement et la discussion thérapeutique. La revue allemande de septembre 2026 décrit une classification TNM 9 qui affine cette distinction ; le support HUG de 2019 ne suffit donc pas pour attribuer un stade actuel. Le cours ne fournit pas de stade ou de pronostic sans ces données.')),
('Les {examens caractérisent la tumeur et préparent le traitement}. Ils répondent à des questions différentes. Le soutien nutritionnel ne doit pas attendre la fin de tous les examens.',table(['Étape','Objectif'],[['9.a : histologie.','Biopsie de la lésion ou prélèvement adapté choisi par l’ORL.'],['9.b : extension locale et régionale.','Imagerie cervicale selon la localisation et les questions opératoires.'],['9.c : bilan d’extension.','Examens complémentaires et endoscopie selon décision oncologique.'],['9.d : fonction et préparation.','Évaluation nutritionnelle, dentaire, déglutition et comorbidités avant traitement.']])) ,
('L’{algorithme évite les traitements empiriques répétés}. Une suspicion doit conduire au spécialiste. La décision thérapeutique vient après caractérisation.',steps('Repérer persistance, progression, unilatéralité, otalgie réflexe ou masse cervicale.','Si obstruction ou saignement important, organiser l’urgence.','Sinon obtenir rapidement un examen ORL avec prélèvement si indiqué.','Réaliser le bilan d’extension et l’évaluation fonctionnelle.','Discuter le traitement en équipe multidisciplinaire et organiser le suivi.')),
('La {prise en charge est multidisciplinaire}. Chirurgie, radiothérapie et traitements systémiques sont choisis selon la tumeur et le patient. Les besoins nutritionnels et fonctionnels sont traités dès le bilan.',paras('<em>11.A — Sécurité.</em> Une obstruction, une hémorragie importante ou une impossibilité de s’alimenter nécessite une prise en charge urgente adaptée.', '<em>11.B — Traitement oncologique.</em> Le support HUG décrit plusieurs modalités. Il ne justifie pas de transposer un schéma unique, une dose de radiothérapie ou une chimiothérapie à tous les cancers oropharyngés ; la décision dépend du stade, des caractéristiques tumorales et du terrain.', '<em>11.C — Soutien.</em> Associer nutrition, soins dentaires, rééducation de la déglutition, prise en charge de la douleur et soutien psychosocial selon les besoins.', '<em>11.D — Suivi.</em> Rechercher récidive, second cancer et séquelles du traitement selon le plan de l’équipe. Les symptômes nouveaux doivent être évalués même entre deux consultations programmées.')),
('La {prévention agit sur les expositions et le repérage précoce}. Aider à l’arrêt du tabac et à la réduction de l’alcool. La vaccination contre le papillomavirus suit les recommandations suisses applicables.',paras('La vaccination ne traite pas une tumeur déjà présente. Son indication préventive dépend du calendrier suisse et du contexte individuel.', 'Après traitement, soutenir la nutrition, la santé buccodentaire et la réadaptation. Une nouvelle douleur, une masse ou une altération de la déglutition impose une réévaluation.')),
('Le {point clé est la plainte persistante ou unilatérale}. Une otalgie avec tympan normal peut être révélatrice. La biopsie et le bilan spécialisé doivent remplacer les prescriptions répétées sans diagnostic.',paras('Le délai de trois semaines est un repère d’alerte du support HUG, pas une permission d’attendre devant un signe très suspect. La prise en charge doit préserver autant que possible fonction et qualité de vie.'))]
q=[('Quel examen confirme le diagnostic ?','L’analyse histologique d’un prélèvement adapté.'),('L’oropharynx comprend-il les amygdales et la base de langue ?','Oui.'),('Une otalgie à tympan normal peut-elle être réflexe ?','Oui.'),('L’absence de tabagisme exclut-elle le cancer ?','Non.'),('Quel repère de persistance cite le support HUG ?','Plus de trois semaines, sans attendre ce délai si le tableau est déjà suspect.'),('Une masse cervicale peut-elle révéler une lésion peu visible ?','Oui.'),('L’imagerie remplace-t-elle la biopsie ?','Non.'),('Que décrit TNM ?','Tumeur, atteinte ganglionnaire et métastases.'),('Une douleur intense suffit-elle à déterminer le stade ?','Non.'),('Qui décide du traitement ?','Une équipe spécialisée multidisciplinaire avec le patient.'),('Faut-il reproduire un schéma oncologique unique pour tous ?','Non.'),('Quels soutiens fonctionnels sont utiles ?','Nutrition, soins dentaires et rééducation de la déglutition selon besoins.'),('La vaccination papillomavirus soigne-t-elle une tumeur ?','Non.'),('Que faire d’un nouveau symptôme entre deux contrôles ?','Le faire réévaluer sans attendre automatiquement le rendez-vous prévu.')]
produire(10,p,q,(3,7,17))
